def area(shape: Shape): Double = shape match {
  case c: Circle => math.Pi * c.r * c.r
  case r: Rect   => r.w * r.h
  case other     => throw new UnsupportedOperationException(s"no area for $other")
}

// the acyclic shape: a visitor that declares only the elements it handles
val circlesOnly: PartialFunction[Shape, Double] = { case c: Circle => math.Pi * c.r * c.r }
